#!/usr/bin/env bash
# Validates the first line of a commit message against Conventional Commits 1.0.0.
# Usage: commit-msg-check.sh <commit-message-file>
set -eu

first_line="$(grep -v '^#' "$1" | head -n 1)"
types='feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert'
pattern="^(${types})(\([a-z0-9._,/-]+\))?!?: .+"

# Merge and revert commits generated by git are allowed.
case "$first_line" in
  Merge\ *|Revert\ \"*) exit 0 ;;
esac

if ! printf '%s' "$first_line" | grep -Eq "$pattern"; then
  echo "Commit message does not follow Conventional Commits 1.0.0:" >&2
  echo "  <type>[optional scope][!]: <description>" >&2
  echo "  types: ${types//|/, }" >&2
  echo "  got:   '${first_line}'" >&2
  exit 1
fi
